export function convertBits(data, fromBits, toBits, pad = true) {
  if (data === null) {
    throw new TypeError("'NoneType' object is not iterable");
  }

  if (fromBits < 0 || toBits < 0 || fromBits + toBits - 1 < 0) {
    throw new ValueError('negative shift count');
  }

  const result = [];
  const fromBase = pow2(fromBits);
  const toBase = pow2(toBits);
  const maxValue = toBase - 1;
  const maxAccumulator = pow2(fromBits + toBits - 1) - 1;
  let accumulator = 0;
  let bits = 0;

  for (const value of data) {
    if (value < 0 || Math.floor(value / fromBase) !== 0) {
      return null;
    }

    accumulator = ((accumulator * fromBase) + value) % (maxAccumulator + 1);
    bits += fromBits;

    while (bits >= toBits) {
      bits -= toBits;
      result.push(Math.floor(accumulator / pow2(bits)) % toBase);
    }
  }

  if (pad) {
    if (bits !== 0) {
      result.push((accumulator * pow2(toBits - bits)) % toBase);
    }
  } else if (bits >= fromBits || ((accumulator * pow2(toBits - bits)) % toBase) !== 0) {
    return null;
  }

  return result;
}

